<script setup>import { onMounted, ref } from 'vue'; import { MoreHorizontal, Search, UserPlus } from 'lucide-vue-next'; import BaseButton from './ui/BaseButton.vue'; import { request } from '../lib/http'; const admins=ref([]); const emit=defineEmits(['notify']); onMounted(async()=>{try{admins.value=(await request('/api/admins')).data}catch(e){emit('notify',e.message)}})</script>
<template><section class="admin-table"><div class="table-head"><div><h2>Administrators</h2><p>Manage access to your workspace.</p></div><BaseButton variant="outline"><UserPlus :size="16"/>Add admin</BaseButton></div><div class="table-search"><Search :size="16"/><input placeholder="Search administrators"/></div><div class="table-scroll"><table><thead><tr><th>Admin</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="admin in admins" :key="admin.id"><td><div class="person"><span class="avatar">{{admin.name.split(' ').map(x=>x[0]).slice(0,2).join('')}}</span><span><b>{{admin.name}}</b><small>{{admin.email}}</small></span></div></td><td>Administrator</td><td><span class="status">Active</span></td><td><button class="plain"><MoreHorizontal :size="19"/></button></td></tr></tbody></table></div></section></template>
